def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    sandwiches = image_patch.find("sandwich half")
    pickles = image_patch.find("pickles")

    if not sandwiches or not pickles:
        return image_patch

    closest_sandwiches = []
    for sandwich in sandwiches:
        min_distance = float('inf')
        for pickle in pickles:
            dist = distance(sandwich, pickle)
            if dist < min_distance:
                min_distance = dist
        closest_sandwiches.append((sandwich, min_distance))

    closest_sandwiches.sort(key=lambda x: x[1])
    return closest_sandwiches[0][0]

